n  2. Run: azd auth login\r\n  3. Your app will use azd credentials\r\n\r\nOption 3: Environment Variables (for CI/CD)\r\n  Set these environment variables:\r\n  - AZURE_CLIENT_ID=your-app-id\r\n  - AZURE_TENANT_ID=your-tenant-id\r\n  - AZURE_CLIENT_SECRET=your-secret\r\n\r\nOption 4: Visual Studio / VS Code\r\n  - Sign in to Azure in your IDE\r\n  - IDE credentials will be used automatically\r\n\r\n⚠️  Make sure your local identity has the same permissions\r\n    as your Managed Identity in Azure!\r\n  `);\r\n}\r\n\r\n/**\r\n * Test your authentication setup\r\n */\r\nexport async function testAuthentication(): Promise\u003cvoid\u003e {\r\n  console.log(\"Testing authentication setup...\\n\");\r\n\r\n  const credential = new DefaultAzureCredential();\r\n\r\n  try {\r\n    // Try to get a token for Azure Resource Manager\r\n    const token = await credential.getToken(\"https://management.azure.com/.default\");\r\n    \r\n    console.log(\"✓ Authentication successful!\");\r\n    console.log(`  Token obtained, expires: ${new Date(token.expiresOnTimestamp)}`);\r\n    console.log(\"\\nYour credential is working correctly. 🎉\");\r\n  } catch (error: any) {\r\n    console.error(\"✗ Authentication failed!\");\r\n    console.error(`  Error: ${error.message}\\n`);\r\n    \r\n    printLocalDevelopmentSetup();\r\n  }\r\n}\r\n\n```\n\n### package.json\n```\n{\r\n  \"name\": \"managed-identity-examples\",\r\n  \"version\": \"1.0.0\",\r\n  \"description\": \"Comprehensive examples for using Azure Managed Identity with Node.js/TypeScript\",\r\n  \"main\": \"complete-example.ts\",\r\n  \"scripts\": {\r\n    \"start\": \"ts-node complete-example.ts\",\r\n    \"validate\": \"ts-node -e \\\"import('./common-pitfalls').then(m =\u003e m.pitfall6_TestingStrategy())\\\"\",\r\n    \"test-auth\": \"ts-node -e \\\"import('./local-development-fallback').then(m =\u003e m.testAuthentication())\\\"\"\r\n  },\r\n  \"keywords\": [\r\n    \"azure\",\r\n    \"managed-identity\",\r\n    \"authentication\",\r\n    \"typescript\",\r\n    \"azure-sdk\"\r\n  ],\r\n  \"author\": \"\",\r\n  \"license\": \"MIT\",\r\n  \"dependencies\": {\r\n    \"@azure/identity\": \"^4.0.0\",\r\n    \"@azure/storage-blob\": \"^12.17.0\",\r\n    \"@azure/storage-queue\": \"^12.16.0\",\r\n    \"@azure/keyvault-secrets\": \"^4.8.0\",\r\n    \"@azure/cosmos\": \"^4.0.0\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/node\": \"^20.10.0\",\r\n    \"typescript\": \"^5.3.0\",\r\n    \"ts-node\": \"^10.9.0\"\r\n  }\r\n}\r\n\n```\n\n### system-assigned-identity.ts\n```\n/**\r\n * System-Assigned Managed Identity Example\r\n * \r\n * A system-assigned identity is tied to your Azure resource (VM, App Service, etc.)\r\n * and is automatically created/deleted with the resource.\r\n * \r\n * Use when: Single resource needs access to Azure services\r\n */\r\n\r\nimport { ManagedIdentityCredential } from \"@azure/identity\";\r\nimport { BlobServiceClient } from \"@azure/storage-blob\";\r\nimport { SecretClient } from \"@azure/keyvault-secrets\";\r\nimport { QueueClient } from \"@azure/storage-queue\";\r\n\r\n/**\r\n * Create a ManagedIdentityCredential for system-assigned identity\r\n * No parameters needed - it automatically uses the system-assigned identity\r\n */\r\nexport function createSystemAssignedCredential(): ManagedIdentityCredential {\r\n  return new ManagedIdentityCredential();\r\n}\r\n\r\n/**\r\n * Example 1: Using system-assigned identity with Azure Blob Storage\r\n */\r\nexport async function accessBlobStorageWithSystemIdentity() {\r\n  const credential = new ManagedIdentityCredential();\r\n  \r\n  const accountName = \"mystorageaccount\";\r\n  const blobServiceClient = new BlobServiceClient(\r\n    `https://${accountName}.blob.core.windows.net`,\r\n    credential\r\n  );\r\n\r\n  try {\r\n    // List containers to verify authentication\r\n    const containers = blobServiceClient.listContainers();\r\n    \r\n    console.log(\"Containers:\");\r\n    for await (const container of containers) {\r\n      console.log(`- ${container.name}`);\r\n    }\r\n  } catch (error) {\r\n    console.error(\"Error accessing blob storage:\", error);\r\n    throw error;\r\n  }\r\n}\r\n\r\n/**\r\n * Example 2: Using system-assigned identity with Azure Key Vault\r\n */\r\nexport async function accessKeyVaultWithSystemIdentity() {\r\n  const credential = new ManagedIdentityCredential();\r\n  \r\n  const vaultUrl = \"https://mykeyvault.vault.azure.net\";\r\n  const secretClient = new SecretClient(vaultUrl, credential);\r\n\r\n  try {\r\n    // Retrieve a secret\r\n    const secretName = \"database-connection-string\";\r\n    const secret = await secretClient.getSecret(secretName);\r\n    \r\n    console.log(`Retrieved secret: ${secretName}`);\r\n    return secret.value;\r\n  } catch (error) {\r\n    console.error(\"Error accessing Key Vault:\", error);\r\n    throw error;\r\n  }\r\n}\r\n\r\n/**\r\n * Example 3: Using system-assigned identity with Azure Queue Storage\r\n */\r\nexport async function accessQueueStorageWithSystemIdentity() {\r\n  const credential = new ManagedIdentityCredential();\r\n  \r\n  const accountName = \"mystorageaccount\";\r\n  const queueName = \"myqueue\";\r\n  \r\n  const queueClient = new QueueClient(\r\n    `https://${accountName}.queue.core.windows.net/${queueName}`,\r\n    credential\r\n  );\r\n\r\n  try {\r\n    // Send a message\r\n    const message = { timestamp: new Date().toISOString(), data: \"test\" };\r\n    await queueClient.sendMessage(JSON.stringify(message));\r\n    \r\n    console.log(\"Message sent successfully\");\r\n  } catch (error) {\r\n    console.error(\"Error accessing queue storage:\", error);\r\n    throw error;\r\n  }\r\n}\r\n\r\n/**\r\n * Example 4: Error handling for system-assigned identity\r\n */\r\nexport async function systemIdentityWithErrorHandling() {\r\n  const credential = new ManagedIdentityCredential();\r\n  const vaultUrl = \"https://mykeyvault.vault.azure.net\";\r\n  const secretClient = new SecretClient(vaultUrl, credential);\r\n\r\n  try {\r\n    const secret = await secretClient.getSecret(\"my-secret\");\r\n    return secret.value;\r\n  } catch (error: any) {\r\n    // Common error scenarios\r\n    if (error.code === \"ManagedIdentityCredential authentication failed\") {\r\n      console.error(\"Managed Identity not enabled or not configured properly\");\r\n      console.error(\"Check: Azure resource has system-assigned identity enabled\");\r\n    } else if (error.statusCode === 403) {\r\n      console.error(\"Access denied - check RBAC permissions\");\r\n      console.error(\"Required: Assign appropriate role (e.g., 'Key Vault Secrets User')\");\r\n    } else if (error.code === \"ENOTFOUND\") {\r\n      console.error(\"Network error - check service endpoint URL\");\r\n    } else {\r\n      console.error(\"Unexpected error:\", error.message);\r\n    }\r\n    throw error;\r\n  }\r\n}\r\n\n```\n\n### user-assigned-identity.ts\n```\n/**\r\n * User-Assigned Managed Identity Example\r\n * \r\n * A user-assigned identity is a standalone Azure resource that can be\r\n * assigned to one or more Azure resources.\r\n * \r\n * Use when: Multiple resources need to share the same identity,\r\n * or you need more control over the identity lifecycle\r\n */\r\n\r\nimport { ManagedIdentityCredential } from \"@azure/identity\";\r\nimport { BlobServiceClient } from \"@azure/storage-blob\";\r\nimport { SecretClient } from \"@azure/keyvault-secrets\";\r\nimport { CosmosClient } from \"@azure/cosmos\";\r\n\r\n/**\r\n * Create a ManagedIdentityCredential for user-assigned identity\r\n * Requires the client ID of the user-assigned managed identity\r\n */\r\nexport function createUserAssignedCredential(clientId: string): ManagedIdentityCredential {\r\n  return new ManagedIdentityCredential({ clientId });\r\n}\r\n\r\n/**\r\n * Alternative: Use resource ID instead of client ID\r\n */\r\nexport function createUserAssignedCredentialWithResourceId(\r\n  resourceId: string\r\n): ManagedIdentityCredential {\r\n  // Resource ID format:\r\n  // /subscriptions/{subscription-id}/resourceGroups/{rg-name}/providers/Microsoft.ManagedIdentity/userAssignedIdentities/{identity-name}\r\n  return new ManagedIdentityCredential({ resourceId });\r\n}\r\n\r\n/**\r\n * Example 1: Using user-assigned identity with configuration from environment\r\n */\r\nexport async function accessBlobStorageWithUserIdentity() {\r\n  // Client ID typically stored in environment variable or configuration\r\n  const clientId = process.env.AZURE_CLIENT_ID || \"12345678-1234-1234-1234-123456789abc\";\r\n  const credential = new ManagedIdentityCredential({ clientId });\r\n  \r\n  const accountName = \"mystorageaccount\";\r\n  const blobServiceClient = new BlobServiceClient(\r\n    `https://${accountName}.blob.core.windows.net`,\r\n    credential\r\n  );\r\n\r\n  try {\r\n    const containerClient = blobServiceClient.getContainerClient(\"mycontainer\");\r\n    \r\n    // Upload a blob\r\n    const blobName = `data-${Date.now()}.json`;\r\n    const data = { message: \"Hello from user-assigned identity\" };\r\n    const blockBlobClient = containerClient.getBlockBlobClient(blobName);\r\n    \r\n    await blockBlobClient.upload(\r\n      JSON.stringify(data),\r\n      JSON.stringify(data).length\r\n    );\r\n    \r\n    console.log(`Blob uploaded: ${blobName}`);\r\n  } catch (error) {\r\n    console.error(\"Error accessing blob storage:\", error);\r\n    throw error;\r\n  }\r\n}\r\n\r\n/**\r\n * Example 2: Using user-assigned identity with Azure Cosmos DB\r\n */\r\nexport async function accessCosmosDbWithUserIdentity() {\r\n  const clientId = process.env.AZURE_CLIENT_ID;\r\n  if (!clientId) {\r\n    throw new Error(\"AZURE_CLIENT_ID environment variable not set\");\r\n  }\r\n  \r\n  const credential = new ManagedIdentityCredential({ clientId });\r\n  \r\n  const endpoint = \"https://mycosmosdb.documents.azure.com:443/\";\r\n  const cosmosClient = new CosmosClient({ endpoint, aadCredentials: credential });\r\n\r\n  try {\r\n    const database = cosmosClient.database(\"mydb\");\r\n    const container = database.container(\"mycollection\");\r\n    \r\n    // Query items\r\n    const { resources } = await container.items\r\n      .query(\"SELECT * FROM c WHERE c.active = true\")\r\n      .fetchAll();\r\n    \r\n    console.log(`Found ${resources.length} active items`);\r\n    return resources;\r\n  } catch (error) {\r\n    console.error(\"Error accessing Cosmos DB:\", error);\r\n    throw error;\r\n  }\r\n}\r\n\r\n/**\r\n * Example 3: Multiple user-assigned identities scenario\r\n * Your resource might have multiple user-assigned identities,\r\n * and you need to specify which one to use\r\n */\r\nexport class MultiIdentityService {\r\n  private storageCredential: ManagedIdentityCredential;\r\n  private keyVaultCredential: ManagedIdentityCredential;\r\n\r\n  constructor(\r\n    private storageIdentityClientId: string,\r\n    private keyVaultIdentityClientId: string\r\n  ) {\r\n    // Create separate credentials for different purposes\r\n    this.storageCredential = new ManagedIdentityCredential({ \r\n      clientId: storageIdentityClientId \r\n    });\r\n    this.keyVaultCredential = new ManagedIdentityCredential({ \r\n      clientId: keyVaultIdentityClientId \r\n    });\r\n  }\r\n\r\n  async accessStorage() {\r\n    const blobServiceClient = new BlobServiceClient(\r\n      \"https://mystorageaccount.blob.core.windows.net\",\r\n      this.storageCredential\r\n    );\r\n    \r\n    // Use storage credential...\r\n  }\r\n\r\n  async accessKeyVault() {\r\n    const secretClient = new SecretClient(\r\n      \"https://mykeyvault.vault.azure.net\",\r\n      this.keyVaultCredential\r\n    );\r\n    \r\n    // Use Key Vault credential...\r\n  }\r\n}\r\n\r\n/**\r\n * Example 4: Comprehensive error handling for user-assigned identity\r\n */\r\nexport async function userIdentityWithErrorHandling(clientId: string) {\r\n  try {\r\n    const credential = new ManagedIdentityCredential({ clientId });\r\n    const vaultUrl = \"https://mykeyvault.vault.azure.net\";\r\n    const secretClient = new SecretClient(vaultUrl, credential);\r\n\r\n    const secret = await secretClient.getSecret(\"my-secret\");\r\n    return secret.value;\r\n  } catch (error: any) {\r\n    if (error.message?.includes(\"No Managed Identity endpoint found\")) {\r\n      console.error(\"ERROR: Not running in an Azure environment with Managed Identity\");\r\n      console.error(\"Solution: Deploy to Azure VM, App Service, Function, or Container Instance\");\r\n    } else if (error.message?.includes(\"the requested identity has not been assigned\")) {\r\n      console.error(`ERROR: User-assigned identity ${clientId} not assigned to this resource`);\r\n      console.error(\"Solution: Assign the identity to your Azure resource\");\r\n    } else if (error.statusCode === 403) {\r\n      console.error(\"ERROR: Identity doesn't have required permissions\");\r\n      console.error(`Solution: Grant the identity (${clientId}) appropriate RBAC role`);\r\n    } else if (error.code === \"SecretNotFound\") {\r\n      console.error(\"ERROR: Secret not found in Key Vault\");\r\n    } else {\r\n      console.error(\"Unexpected error:\", error);\r\n    }\r\n    throw error;\r\n  }\r\n}\r\n\r\n/**\r\n * Example 5: Validating user-assigned identity configuration\r\n */\r\nexport async function validateUserAssignedIdentity(clientId: string): Promise\u003cboolean\u003e {\r\n  try {\r\n    const credential = new ManagedIdentityCredential({ clientId });\r\n    \r\n    // Try to get a token (doesn't call any actual service)\r\n    const token = await credential.getToken(\"https://management.azure.com/.default\");\r\n    \r\n    if (token) {\r\n      console.log(\"✓ User-assigned identity authenticated successfully\");\r\n      console.log(`  Token expires: ${new Date(token.expiresOnTimestamp)}`);\r\n      return true;\r\n    }\r\n    \r\n    return false;\r\n  } catch (error: any) {\r\n    console.error(\"✗ Failed to authenticate with user-assigned identity\");\r\n    console.error(`  Client ID: ${clientId}`);\r\n    console.error(`  Error: ${error.message}`);\r\n    return false;\r\n  }\r\n}\r\n\n```\n\n### README.md\n```\n# Azure Managed Identity with Node.js/TypeScript\r\n\r\nComprehensive guide and examples for using Azure Managed Identity to authenticate Azure SDK clients in Node.js applications.\r\n\r\n## 📋 Table of Contents\r\n\r\n1. [System-Assigned vs User-Assigned Identity](#identity-types)\r\n2. [Creating Credentials](#creating-credentials)\r\n3. [Using with Azure SDK Clients](#using-with-sdk)\r\n4. [Local Development Fallback](#local-development)\r\n5. [Common Pitfalls](#common-pitfalls)\r\n6. [Complete Example](#complete-example)\r\n\r\n## 🔐 Identity Types\r\n\r\n### System-Assigned Identity\r\n- **Lifecycle**: Tied to your Azure resource (VM, App Service, etc.)\r\n- **Creation**: Automatically created/deleted with the resource\r\n- **Use case**: Single resource needs access to Azure services\r\n- **Example**: `system-assigned-identity.ts`\r\n\r\n```typescript\r\nimport { ManagedIdentityCredential } from \"@azure/identity\";\r\n\r\n// No parameters needed - uses system-assigned identity\r\nconst credential = new ManagedIdentityCredential();\r\n```\r\n\r\n### User-Assigned Identity\r\n- **Lifecycle**: Standalone Azure resource, independent lifecycle\r\n- **Creation**: Created separately, can be assigned to multiple resources\r\n- **Use case**: Multiple resources sharing the same identity, or need identity lifecycle control\r\n- **Example**: `user-assigned-identity.ts`\r\n\r\n```typescript\r\nimport { ManagedIdentityCredential } from \"@azure/identity\";\r\n\r\n// Requires client ID of the user-assigned identity\r\nconst credential = new ManagedIdentityCredential({ \r\n  clientId: \"12345678-1234-1234-1234-123456789abc\" \r\n});\r\n```\r\n\r\n## 🛠️ Creating Credentials\r\n\r\n### System-Assigned\r\n```typescript\r\n// Simple - no parameters\r\nconst credential = new ManagedIdentityCredential();\r\n```\r\n\r\n### User-Assigned (by Client ID)\r\n```typescript\r\nconst credential = new ManagedIdentityCredential({ \r\n  clientId: process.env.AZURE_CLIENT_ID \r\n});\r\n```\r\n\r\n### User-Assigned (by Resource ID)\r\n```typescript\r\nconst credential = new ManagedIdentityCredential({ \r\n  resourceId: \"/subscriptions/{sub}/resourceGroups/{rg}/providers/Microsoft.ManagedIdentity/userAssignedIdentities/{name}\"\r\n});\r\n```\r\n\r\n### Best Practice: DefaultAzureCredential\r\n```typescript\r\nimport { DefaultAzureCredential } from \"@azure/identity\";\r\n\r\n// Works everywhere: Azure (Managed Identity), Local (Azure CLI), CI/CD (Service Principal)\r\nconst credential = new DefaultAzureCredential({\r\n  managedIdentityClientId: process.env.AZURE_CLIENT_ID // optional for user-assigned\r\n});\r\n```\r\n\r\n## 🔌 Using with Azure SDK Clients\r\n\r\n### Blob Storage\r\n```typescript\r\nimport { BlobServiceClient } from \"@azure/storage-blob\";\r\n\r\nconst credential = new ManagedIdentityCredential();\r\nconst blobServiceClient = new BlobServiceClient(\r\n  `https://${accountName}.blob.core.windows.net`,\r\n  credential\r\n);\r\n\r\n// Use the client\r\nconst containers = blobServiceClient.listContainers();\r\nfor await (const container of containers) {\r\n  console.log(container.name);\r\n}\r\n```\r\n\r\n### Key Vault\r\n```typescript\r\nimport { SecretClient } from \"@azure/keyvault-secrets\";\r\n\r\nconst credential = new ManagedIdentityCredential();\r\nconst secretClient = new SecretClient(\r\n  \"https://mykeyvault.vault.azure.net\",\r\n  credential\r\n);\r\n\r\nconst secret = await secretClient.getSecret(\"my-secret\");\r\nconsole.log(secret.value);\r\n```\r\n\r\n### Cosmos DB\r\n```typescript\r\nimport { CosmosClient } from \"@azure/cosmos\";\r\n\r\nconst credential = new ManagedIdentityCredential();\r\nconst cosmosClient = new CosmosClient({ \r\n  endpoint: \"https://mycosmosdb.documents.azure.com:443/\",\r\n  aadCredentials: credential \r\n});\r\n```\r\n\r\nSee `complete-example.ts` for a full production-ready implementation.\r\n\r\n## 💻 Local Development Fallback\r\n\r\nManaged Identity only works in Azure. For local development:\r\n\r\n### Option 1: DefaultAzureCredential (Recommended)\r\n```typescript\r\nimport { DefaultAzureCredential } from \"@azure/identity\";\r\n\r\n// Automatically falls back to Azure CLI, Environment Variables, etc.\r\nconst credential = new DefaultAzureCredential();\r\n```\r\n\r\n**Credential chain order:**\r\n1. Environment variables (service principal)\r\n2. Workload Identity (Kubernetes)\r\n3. **Managed Identity** (Azure)\r\n4. **Azure CLI** (local dev)\r\n5. Azure PowerShell\r\n6. Azure Developer CLI\r\n\r\n### Option 2: Azure CLI\r\n```bash\r\n# One-time setup\r\naz login\r\naz account set --subscription \"your-subscription\"\r\n\r\n# Your app automatically uses these credentials locally\r\n```\r\n\r\n### Option 3: Custom Chain\r\n```typescript\r\nimport { ChainedTokenCredential, ManagedIdentityCredential, AzureCliCredential } from \"@azure/identity\";\r\n\r\nconst credential = new ChainedTokenCredential(\r\n  new ManagedIdentityCredential({ clientId: process.env.AZURE_CLIENT_ID }),\r\n  new AzureCliCredential()\r\n);\r\n```\r\n\r\n### Option 4: Environment-Based Selection\r\n```typescript\r\nconst isAzure = process.env.WEBSITE_INSTANCE_ID || process.env.IDENTITY_ENDPOINT;\r\n\r\nconst credential = isAzure\r\n  ? new ManagedIdentityCredential()\r\n  : new AzureCliCredential();\r\n```\r\n\r\nSee `local-development-fallback.ts` for all strategies.\r\n\r\n## ⚠️ Common Pitfalls\r\n\r\n### 1. Identity Not Enabled\r\n**Error:** \"No Managed Identity endpoint found\"\r\n\r\n**Solution:**\r\n```bash\r\n# Enable system-assigned identity\r\naz vm identity assign --name myVM --resource-group myRG\r\naz webapp identity assign --name myApp --resource-group myRG\r\n```\r\n\r\n### 2. Missing RBAC Permissions\r\n**Error:** 403 Forbidden\r\n\r\n**Solution:**\r\n```bash\r\n# Get identity principal ID\r\nprincipalId=$(az vm identity show --name myVM --resource-group myRG --query principalId -o tsv)\r\n\r\n# Assign role\r\naz role assignment create \\\r\n  --role \"Key Vault Secrets User\" \\\r\n  --assignee $principalId \\\r\n  --scope /subscriptions/{sub}/resourceGroups/{rg}/providers/Microsoft.KeyVault/vaults/{vault}\r\n```\r\n\r\n**Common roles:**\r\n- `Storage Blob Data Contributor`\r\n- `Storage Queue Data Contributor`\r\n- `Key Vault Secrets User`\r\n- `Cosmos DB Account Reader Role`\r\n\r\n### 3. Wrong Client ID\r\n**Error:** \"The requested identity has not been assigned\"\r\n\r\n**Solution:**\r\n1. Verify client ID: Azure Portal → Managed Identities → Your Identity → Properties\r\n2. Assign to resource: Azure Portal → Your Resource → Identity → User assigned → Add\r\n\r\n### 4. No Retry Logic\r\n**Solution:** Implement retries for transient errors (429, 503, 504)\r\n\r\n```typescript\r\nfor (let attempt = 1; attempt \u003c= maxRetries; attempt++) {\r\n  try {\r\n    return await operation();\r\n  } catch (error) {\r\n    if (isTransient(error) \u0026\u0026 attempt \u003c maxRetries) {\r\n      await delay(retryDelayMs * attempt);\r\n    } else {\r\n      throw error;\r\n    }\r\n  }\r\n}\r\n```\r\n\r\n### 5. Hardcoded Resource URLs\r\n**Solution:** Use environment variables\r\n\r\n```typescript\r\nconst storageAccountName = process.env.AZURE_STORAGE_ACCOUNT_NAME;\r\nconst keyVaultName = process.env.AZURE_KEYVAULT_NAME;\r\n```\r\n\r\nSee `common-pitfalls.ts` for detailed error handling.\r\n\r\n## 🚀 Complete Example\r\n\r\nSee `complete-example.ts` for a production-ready application that:\r\n- ✅ Uses DefaultAzureCredential for flexibility\r\n- ✅ Validates authentication and permissions\r\n- ✅ Handles errors gracefully\r\n- ✅ Supports both identity types\r\n- ✅ Uses environment variables for configuration\r\n- ✅ Includes comprehensive logging\r\n\r\n### Running the Example\r\n\r\n```bash\r\n# Install dependencies\r\nnpm install\r\n\r\n# Set environment variables\r\nexport AZURE_STORAGE_ACCOUNT_NAME=\"mystorageaccount\"\r\nexport AZURE_KEYVAULT_NAME=\"mykeyvault\"\r\nexport AZURE_QUEUE_NAME=\"tasks\"\r\nexport AZURE_CLIENT_ID=\"...\" # Optional for user-assigned identity\r\n\r\n# Run\r\nnpm start\r\n\r\n# Test authentication\r\nnpm run test-auth\r\n```\r\n\r\n## 📦 Dependencies\r\n\r\n```json\r\n{\r\n  \"dependencies\": {\r\n    \"@azure/identity\": \"^4.0.0\",\r\n    \"@azure/storage-blob\": \"^12.17.0\",\r\n    \"@azure/storage-queue\": \"^12.16.0\",\r\n    \"@azure/keyvault-secrets\": \"^4.8.0\",\r\n    \"@azure/cosmos\": \"^4.0.0\"\r\n  }\r\n}\r\n```\r\n\r\n## 🎯 Best Practices\r\n\r\n1. ✅ **Use `DefaultAzureCredential`** - Works everywhere (Azure, local, CI/CD)\r\n2. ✅ **System-assigned when possible** - Simpler lifecycle management\r\n3. ✅ **Least privilege** - Grant only necessary RBAC permissions\r\n4. ✅ **Handle errors gracefully** - Implement retry logic\r\n5. ✅ **Test thoroughly** - Local → Staging → Production\r\n6. ✅ **Use environment variables** - Never hardcode resource names\r\n7. ✅ **Monitor authentication** - Track failures with Application Insights\r\n8. ✅ **Document permissions** - Document required roles and assignments\r\n\r\n## 📚 Files in This Repository\r\n\r\n- `system-assigned-identity.ts` - Examples using system-assigned identity\r\n- `user-assigned-identity.ts` - Examples using user-assigned identity\r\n- `local-development-fallback.ts` - Strategies for local development\r\n- `common-pitfalls.ts` - Error handling and troubleshooting\r\n- `complete-example.ts` - Production-ready full application\r\n- `package.json` - Dependencies and scripts\r\n- `README.md` - This file\r\n\r\n## 🔗 Resources\r\n\r\n- [Azure Identity SDK for JavaScript](https://github.com/Azure/azure-sdk-for-js/tree/main/sdk/identity/identity)\r\n- [Managed identities for Azure resources](https://docs.microsoft.com/azure/active-directory/managed-identities-azure-resources/overview)\r\n- [DefaultAzureCredential documentation](https://docs.microsoft.com/javascript/api/@azure/identity/defaultazurecredential)\r\n- [Azure RBAC roles](https://docs.microsoft.com/azure/role-based-access-control/built-in-roles)\r\n\r\n## 💡 Quick Start\r\n\r\n```typescript\r\nimport { DefaultAzureCredential } from \"@azure/identity\";\r\nimport { BlobServiceClient } from \"@azure/storage-blob\";\r\n\r\n// Works in Azure AND locally (with az login)\r\nconst credential = new DefaultAzureCredential();\r\n\r\nconst blobServiceClient = new BlobServiceClient(\r\n  `https://${process.env.AZURE_STORAGE_ACCOUNT_NAME}.blob.core.windows.net`,\r\n  credential\r\n);\r\n\r\n// Use the client!\r\nconst containers = blobServiceClient.listContainers();\r\nfor await (const container of containers) {\r\n  console.log(container.name);\r\n}\r\n```\r\n\r\nThat's it! The credential automatically:\r\n- Uses Managed Identity in Azure\r\n- Uses Azure CLI when running locally\r\n- Uses Service Principal in CI/CD\r\n\r\n---\r\n\r\nFor questions or issues, refer to the detailed examples in each file.\r\n\n```\n\n### common-pitfalls.ts\n```\n/**\r\n * Common Pitfalls and Error Handling\r\n * \r\n * This file covers common issues developers encounter when using\r\n * Managed Identity and how to handle them properly.\r\n */\r\n\r\nimport {\r\n  ManagedIdentityCredential,\r\n  DefaultAzureCredential,\r\n  TokenCredential,\r\n} from \"@azure/identity\";\r\nimport { SecretClient } from \"@azure/keyvault-secrets\";\r\nimport { BlobServiceClient } from \"@azure/storage-blob\";\r\n\r\n/**\r\n * PITFALL 1: Not enabling Managed Identity on the Azure resource\r\n * \r\n * Error: \"No MSI credential available\"\r\n * Solution: Enable system-assigned or assign user-assigned identity\r\n */\r\nexport async function pitfall1_IdentityNotEnabled() {\r\n  try {\r\n    const credential = new ManagedIdentityCredential();\r\n    const token = await credential.getToken(\"https://vault.azure.net/.default\");\r\n    console.log(\"Identity is enabled ✓\");\r\n  } catch (error: any) {\r\n    if (error.message?.includes(\"No Managed Identity endpoint found\")) {\r\n      console.error(\"PITFALL: Managed Identity not enabled\");\r\n      console.error(\"\\nSOLUTION:\");\r\n      console.error(\"1. Azure Portal → Your Resource → Identity\");\r\n      console.error(\"2. Enable 'System assigned' OR assign a 'User assigned' identity\");\r\n      console.error(\"3. Save and redeploy your application\");\r\n      console.error(\"\\nCLI Command:\");\r\n      console.error(\"  az vm identity assign --name myVM --resource-group myRG\");\r\n      console.error(\"  az webapp identity assign --name myApp --resource-group myRG\");\r\n    }\r\n    throw error;\r\n  }\r\n}\r\n\r\n/**\r\n * PITFALL 2: Missing RBAC permissions\r\n * \r\n * Error: 403 Forbidden\r\n * Solution: Assign appropriate role to the identity\r\n */\r\nexport async function pitfall2_MissingPermissions() {\r\n  const credential = new ManagedIdentityCredential();\r\n  const secretClient = new SecretClient(\"https://mykeyvault.vault.azure.net\", credential);\r\n\r\n  try {\r\n    await secretClient.getSecret(\"my-secret\");\r\n  } catch (error: any) {\r\n    if (error.statusCode === 403) {\r\n      console.error(\"PITFALL: Missing RBAC permissions\");\r\n      console.error(\"\\nSOLUTION:\");\r\n      console.error(\"1. Azure Portal → Key Vault → Access control (IAM)\");\r\n      console.error(\"2. Add role assignment:\");\r\n      console.error(\"   - Role: 'Key Vault Secrets User' (or appropriate role)\");\r\n      console.error(\"   - Assign to: Your Managed Identity\");\r\n      console.error(\"\\nCLI Command:\");\r\n      console.error(\"  # Get the principal ID of your managed identity\");\r\n      console.error(\"  principalId=$(az vm identity show --name myVM --resource-group myRG --query principalId -o tsv)\");\r\n      console.error(\"  # Assign role\");\r\n      console.error(\"  az role assignment create \\\\\");\r\n      console.error(\"    --role 'Key Vault Secrets User' \\\\\");\r\n      console.error(\"    --assignee $principalId \\\\\");\r\n      console.error(\"    --scope /subscriptions/{sub}/resourceGroups/{rg}/providers/Microsoft.KeyVault/vaults/{vault}\");\r\n      console.error(\"\\nCommon Roles:\");\r\n      console.error(\"  - Storage Blob Data Contributor\");\r\n      console.error(\"  - Storage Queue Data Contributor\");\r\n      console.error(\"  - Key Vault Secrets User\");\r\n      console.error(\"  - Cosmos DB Account Reader Role\");\r\n    }\r\n    throw error;\r\n  }\r\n}\r\n\r\n/**\r\n * PITFALL 3: Using wrong client ID for user-assigned identity\r\n * \r\n * Error: \"The requested identity has not been assigned\"\r\n * Solution: Verify the client ID and assignment\r\n */\r\nexport async function pitfall3_WrongClientId(clientId: string) {\r\n  try {\r\n    const credential = new ManagedIdentityCredential({ clientId });\r\n    await credential.getToken(\"https://vault.azure.net/.default\");\r\n  } catch (error: any) {\r\n    if (error.message?.includes(\"not been assigned\")) {\r\n      console.error(\"PITFALL: Wrong client ID or identity not assigned\");\r\n      console.error(`\\nProvided Client ID: ${clientId}`);\r\n      console.error(\"\\nSOLUTION:\");\r\n      console.error(\"1. Verify the client ID is correct:\");\r\n      console.error(\"   Azure Portal → Managed Identities → Your Identity → Properties → Client ID\");\r\n      console.error(\"\\n2. Ensure identity is assigned to your resource:\");\r\n      console.error(\"   Azure Portal → Your Resource → Identity → User assigned → Add\");\r\n      console.error(\"\\nCLI Commands:\");\r\n      console.error(\"  # List user-assigned identities\");\r\n      console.error(\"  az identity list --resource-group myRG\");\r\n      console.error(\"  # Assign to VM\");\r\n      console.error(\"  az vm identity assign --name myVM --resource-group myRG \\\\\");\r\n      console.error(\"    --identities /subscriptions/{sub}/resourceGroups/{rg}/providers/Microsoft.ManagedIdentity/userAssignedIdentities/{identity-name}\");\r\n    }\r\n    throw error;\r\n  }\r\n}\r\n\r\n/**\r\n * PITFALL 4: Token expiration not handled\r\n * \r\n * The SDK handles token refresh automatically, but you should\r\n * be aware of it for long-running operations\r\n */\r\nexport async function pitfall4_TokenExpiration() {\r\n  const credential = new ManagedIdentityCredential();\r\n  \r\n  // ✓ GOOD: SDK clients handle token refresh automatically\r\n  const blobServiceClient = new BlobServiceClient(\r\n    \"https://mystorageaccount.blob.core.windows.net\",\r\n    credential\r\n  );\r\n\r\n  // This will work even in long-running operations\r\n  // The credential automatically refreshes tokens as needed\r\n  for (let i = 0; i \u003c 100; i++) {\r\n    await blobServiceClient.getContainerClient(`container-${i}`).exists();\r\n    // No need to manually refresh token\r\n  }\r\n\r\n  console.log(\"✓ Token refresh is handled automatically by Azure SDK\");\r\n}\r\n\r\n/**\r\n * PITFALL 5: Not handling transient failures\r\n * \r\n * Solution: Implement retry logic for transient errors\r\n */\r\nexport async function pitfall5_NoRetryLogic() {\r\n  const credential = new ManagedIdentityCredential();\r\n  const secretClient = new SecretClient(\"https://mykeyvault.vault.azure.net\", credential);\r\n\r\n  // ✗ BAD: No retry logic\r\n  // await secretClient.getSecret(\"my-secret\");\r\n\r\n  // ✓ GOOD: With retry logic\r\n  const maxRetries = 3;\r\n  const retryDelayMs = 1000;\r\n\r\n  for (let attempt = 1; attempt \u003c= maxRetries; attempt++) {\r\n    try {\r\n      const secret = await secretClient.getSecret(\"my-secret\");\r\n      console.log(\"✓ Secret retrieved successfully\");\r\n      return secret.value;\r\n    } catch (error: any) {\r\n      const isTransient = \r\n        error.statusCode === 429 || // Too many requests\r\n        error.statusCode === 503 || // Service unavailable\r\n        error.statusCode === 504 || // Gateway timeout\r\n        error.code === \"ETIMEDOUT\" ||\r\n        error.code === \"ECONNRESET\";\r\n\r\n      if (isTransient \u0026\u0026 attempt \u003c maxRetries) {\r\n        console.log(`Transient error, retrying (${attempt}/${maxRetries})...`);\r\n        await new Promise(resolve =\u003e setTimeout(resolve, retryDelayMs * attempt));\r\n      } else {\r\n        throw error;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n/**\r\n * PITFALL 6: Testing in production first\r\n * \r\n * Solution: Test locally and validate before deploying\r\n */\r\nexport async function pitfall6_TestingStrategy() {\r\n  console.log(\"TESTING STRATEGY:\\n\");\r\n\r\n  console.log(\"1. LOCAL TESTING:\");\r\n  console.log(\"   - Use Azure CLI: az login\");\r\n  console.log(\"   - Use DefaultAzureCredential in your code\");\r\n  console.log(\"   - Verify your user account has the same permissions\\n\");\r\n\r\n  console.log(\"2. VALIDATION:\");\r\n  console.log(\"   - Test authentication before using services\");\r\n  \r\n  try {\r\n    const credential = new DefaultAzureCredential();\r\n    await credential.getToken(\"https://vault.azure.net/.default\");\r\n    console.log(\"   ✓ Credential validation successful\\n\");\r\n  } catch (error: any) {\r\n    console.log(\"   ✗ Credential validation failed\");\r\n    console.log(`   Error: ${error.message}\\n`);\r\n  }\r\n\r\n  console.log(\"3. STAGING ENVIRONMENT:\");\r\n  console.log(\"   - Deploy to staging with Managed Identity enabled\");\r\n  console.log(\"   - Verify permissions are correctly assigned\");\r\n  console.log(\"   - Test all Azure service integrations\\n\");\r\n\r\n  console.log(\"4. MONITORING:\");\r\n  console.log(\"   - Enable Application Insights\");\r\n  console.log(\"   - Monitor authentication failures\");\r\n  console.log(\"   - Set up alerts for 401/403 errors\");\r\n}\r\n\r\n/**\r\n * PITFALL 7: Hardcoding resource URLs\r\n * \r\n * Solution: Use environment variables or configuration\r\n */\r\nexport class ConfigurableAzureService {\r\n  private credential: TokenCredential;\r\n  private storageAccountName: string;\r\n  private keyVaultName: string;\r\n\r\n  constructor() {\r\n    // ✓ GOOD: Read from environment variables\r\n    this.storageAccountName = process.env.AZURE_STORAGE_ACCOUNT_NAME || \"\";\r\n    this.keyVaultName = process.env.AZURE_KEYVAULT_NAME || \"\";\r\n    \r\n    const userAssignedClientId = process.env.AZURE_CLIENT_ID;\r\n    \r\n    this.credential = new DefaultAzureCredential({\r\n      managedIdentityClientId: userAssignedClientId,\r\n    });\r\n\r\n    this.validate();\r\n  }\r\n\r\n  private validate(): void {\r\n    if (!this.storageAccountName) {\r\n      throw new Error(\"AZURE_STORAGE_ACCOUNT_NAME environment variable not set\");\r\n    }\r\n    if (!this.keyVaultName) {\r\n      throw new Error(\"AZURE_KEYVAULT_NAME environment variable not set\");\r\n    }\r\n  }\r\n\r\n  getBlobServiceClient(): BlobServiceClient {\r\n    return new BlobServiceClient(\r\n      `https://${this.storageAccountName}.blob.core.windows.net`,\r\n      this.credential\r\n    );\r\n  }\r\n\r\n  getSecretClient(): SecretClient {\r\n    return new SecretClient(\r\n      `https://${this.keyVaultName}.vault.azure.net`,\r\n      this.credential\r\n    );\r\n  }\r\n}\r\n\r\n/**\r\n * PITFALL 8: Not understanding scope requirements\r\n * \r\n * Different Azure services require different token scopes\r\n */\r\nexport async function pitfall8_IncorrectScopes() {\r\n  const credential = new ManagedIdentityCredential();\r\n\r\n  console.log(\"TOKEN SCOPES FOR DIFFERENT SERVICES:\\n\");\r\n\r\n  const scopes = {\r\n    \"Storage\": \"https://storage.azure.com/.default\",\r\n    \"Key Vault\": \"https://vault.azure.net/.default\",\r\n    \"Azure Resource Manager\": \"https://management.azure.com/.default\",\r\n    \"Microsoft Graph\": \"https://graph.microsoft.com/.default\",\r\n    \"Cosmos DB\": \"https://cosmos.azure.com/.default\",\r\n  };\r\n\r\n  for (const [service, scope] of Object.entries(scopes)) {\r\n    try {\r\n      await credential.getToken(scope);\r\n      console.log(`✓ ${service}: ${scope}`);\r\n    } catch (error) {\r\n      console.log(`✗ ${service}: ${scope} (requires permission)`);\r\n    }\r\n  }\r\n\r\n  console.log(\"\\nNote: SDK clients automatically use the correct scope\");\r\n}\r\n\r\n/**\r\n * Comprehensive error handler\r\n */\r\nexport async function handleManagedIdentityError(error: any): Promise\u003cvoid\u003e {\r\n  console.error(\"\\n🔴 MANAGED IDENTITY ERROR DETECTED\\n\");\r\n\r\n  // Check error type and provide specific guidance\r\n  const errorMsg = error.message?.toLowerCase() || \"\";\r\n  const errorCode = error.code || \"\";\r\n  const statusCode = error.statusCode || 0;\r\n\r\n  if (errorMsg.includes(\"no managed identity endpoint\")) {\r\n    console.error(\"Issue: Managed Identity not available\");\r\n    console.error(\"Cause: Not running in Azure OR identity not enabled\");\r\n    console.error(\"Fix: Enable identity on your Azure resource\\n\");\r\n  } else if (errorMsg.includes(\"not been assigned\")) {\r\n    console.error(\"Issue: User-assigned identity not assigned to resource\");\r\n    console.error(\"Fix: Assign the identity or check the client ID\\n\");\r\n  } else if (statusCode === 403) {\r\n    console.error(\"Issue: Permission denied\");\r\n    console.error(\"Fix: Grant appropriate RBAC role to the identity\\n\");\r\n  } else if (statusCode === 401) {\r\n    console.error(\"Issue: Authentication failed\");\r\n    console.error(\"Fix: Verify identity is properly configured\\n\");\r\n  } else if (statusCode === 429) {\r\n    console.error(\"Issue: Too many requests\");\r\n    console.error(\"Fix: Implement backoff/retry logic\\n\");\r\n  } else if (errorCode === \"ENOTFOUND\") {\r\n    console.error(\"Issue: Service endpoint not found\");\r\n    console.error(\"Fix: Check the resource URL\\n\");\r\n  } else {\r\n    console.error(`Issue: Unexpected error`);\r\n    console.error(`Error: ${error.message}`);\r\n    console.error(`Code: ${errorCode}`);\r\n    console.error(`Status: ${statusCode}\\n`);\r\n  }\r\n\r\n  console.error(\"Full error details:\", error);\r\n}\r\n\r\n/**\r\n * Best practices summary\r\n */\r\nexport function printBestPractices(): void {\r\n  console.log(`\r\n✨ MANAGED IDENTITY BEST PRACTICES\r\n\r\n1. ✓ Use DefaultAzureCredential for maximum flexibility\r\n   - Works in Azure with Managed Identity\r\n   - Works locally with Azure CLI\r\n   - Works in CI/CD with service principals\r\n\r\n2. ✓ Use system-assigned identity when possible\r\n   - Simpler to manage\r\n   - Automatic lifecycle with resource\r\n   - Use user-assigned when sharing across resources\r\n\r\n3. ✓ Follow principle of least privilege\r\n   - Grant only necessary permissions\r\n   - Use specific RBAC roles, not broad ones\r\n   - Regularly review and audit permissions\r\n\r\n4. ✓ Handle errors gracefully\r\n   - Implement retry logic for transient failures\r\n   - Log authentication errors for monitoring\r\n   - Provide helpful error messages\r\n\r\n5. ✓ Test thoroughly\r\n   - Test locally with Azure CLI\r\n   - Test in staging with actual Managed Identity\r\n   - Validate permissions before production\r\n\r\n6. ✓ Use environment variables for configuration\r\n   - Never hardcode resource names\r\n   - Use different configs for dev/staging/prod\r\n   - Keep client IDs in configuration, not code\r\n\r\n7. ✓ Monitor authentication\r\n   - Enable Application Insights\r\n   - Track authentication failures\r\n   - Set up alerts for permission issues\r\n\r\n8. ✓ Document your setup\r\n   - Document required permissions\r\n   - Document identity assignments\r\n   - Provide setup guide for new developers\r\n  `);\r\n}\r\n\n```\n\n### complete-example.ts\n```\n/**\r\n * Complete Production-Ready Example\r\n * \r\n * This demonstrates a full application using Managed Identity\r\n * with proper error handling, configuration, and fallback